def orderOfLargestPlusSign(n, mines):
    # Initialize DP grid with n's (max possible for each arm)
    dp = [[n] * n for _ in range(n)]
    mines_set = set((x, y) for x, y in mines)

    # Scan left to right
    for i in range(n):
        count = 0
        for j in range(n):
            if (i, j) in mines_set:
                count = 0
            else:
                count += 1
            dp[i][j] = min(dp[i][j], count)
        # Scan right to left
        count = 0
        for j in range(n - 1, -1, -1):
            if (i, j) in mines_set:
                count = 0
            else:
                count += 1
            dp[i][j] = min(dp[i][j], count)

    # Scan top to bottom
    for j in range(n):
        count = 0
        for i in range(n):
            if (i, j) in mines_set:
                count = 0
            else:
                count += 1
            dp[i][j] = min(dp[i][j], count)
        # Scan bottom to top
        count = 0
        for i in range(n - 1, -1, -1):
            if (i, j) in mines_set:
                count = 0
            else:
                count += 1
            dp[i][j] = min(dp[i][j], count)

    # The result is the largest value in dp
    res = 0
    for row in dp:
        for val in row:
            res = max(res, val)
    return res
